      const toggle = document.getElementById(toggleId);
      const dropdown = document.getElementById(dropdownId);
      if (!toggle || !dropdown) return null;

      let closeTimer = null;
      let isOpen = false;

      // The base glyph is a down chevron. Collapsed it points right, the way a
